import bisect, hashlib

def h(s: str) -> int:
    # Stable across processes, unlike Python's salted built-in hash()
    return int.from_bytes(hashlib.md5(s.encode()).digest()[:8], "big")

class HashRing:
    def __init__(self, nodes: list[str], vnodes: int = 128):
        self.vnodes, self.ring = vnodes, []  # ring: sorted (token, node)
        for n in nodes:
            self.add(n)

    def add(self, node: str) -> None:
        for i in range(self.vnodes):  # many points per node evens out load
            bisect.insort(self.ring, (h(f"{node}#{i}"), node))

    def remove(self, node: str) -> None:
        self.ring = [(t, n) for t, n in self.ring if n != node]

    def get(self, key: str) -> str:
        i = bisect.bisect(self.ring, (h(key), ""))  # first token clockwise
        return self.ring[i % len(self.ring)][1]     # wrap around the ring

ring = HashRing([f"gpu-{i}" for i in range(10)])
keys = [f"session:{i}" for i in range(100_000)]
before = {k: ring.get(k) for k in keys}
ring.add("gpu-10")
moved = sum(before[k] != ring.get(k) for k in keys) / len(keys)
print(f"{moved:.1%} of sessions moved")  # ~9-10% (ideal 1/11); hash % N moves ~91%
